use crate::{engine::*,model::*,rpc::Rpc};
use std::{fs,path::{Path,PathBuf},sync::{Arc,Barrier,atomic::Ordering},time::{Duration,Instant}};
use serde_json::{json,Value};
fn until(test:impl Fn()->bool){let end=Instant::now()+Duration::from_secs(8);while !test()&&Instant::now()<end{std::thread::sleep(Duration::from_millis(20));}assert!(test(),"bounded mock wait failed");}
fn setup(case:&str)->(Arc<Engine>,PathBuf){
 let base=PathBuf::from(std::env::var_os("AI_GUILD_TEST_ROOT").expect("Explicit isolated test root required"));let root=base.join(format!("mock-{case}-{}",id()));fs::create_dir_all(&root).unwrap();fs::write(root.join(".ai-guild-qa"),"MOCK ONLY / no inference").unwrap();std::env::set_var("AI_GUILD_QA_DATA_DIR",&root);
 let e=Engine::open(&root,None).unwrap();let(rpc,version)=Rpc::spawn_qa_peer().unwrap();*e.rpc.lock().unwrap()=Some(rpc);
 e.update(|s|{s.connection.status="connected".into();s.connection.version=version;s.workflow.nodes.truncate(1);s.workflow.edges.clear();s.workflow.nodes[0].dependencies.clear();s.workflow.nodes[0].work_instruction=format!("QA_CASE={case}");Ok(())}).unwrap();e.start(format!("MOCK ONLY QA_CASE={case}")).unwrap();(e,root)
}
fn approval(e:&Engine)->Approval{until(||e.snapshot().approvals.iter().any(|a|!a.resolved));e.snapshot().approvals.iter().find(|a|!a.resolved).unwrap().clone()}
fn finish(e:&Engine){until(||!e.worker.load(Ordering::SeqCst));}
fn peer_records(root:&Path)->Vec<Value>{fs::read_to_string(root.join("mock-peer.jsonl")).unwrap().lines().map(|s|serde_json::from_str(s).unwrap()).collect()}
#[test]fn phase7_mock_protocol_regressions(){
 let mut checks=Vec::<Value>::new();
 let(e,root)=setup("questions");let a=approval(&e);let secret=format!("qa-{}-{}",id(),id());
 let answers=std::collections::HashMap::from([("format".into(),vec!["Markdown".into()]),("audience".into(),vec!["QA audience".into()]),("private".into(),vec![secret.clone()])]);
 let barrier=Arc::new(Barrier::new(3));let mut handles=vec![];
 for _ in 0..2{let(e,a,answers,b)=(e.clone(),a.clone(),answers.clone(),barrier.clone());handles.push(std::thread::spawn(move||{b.wait();e.answer_structured(a.id,"accept".into(),String::new(),Some(answers)).is_ok()}));}barrier.wait();let accepted=handles.into_iter().filter_map(|h|h.join().ok()).filter(|r|*r).count();finish(&e);
 let rows=peer_records(&root);checks.push(json!({"name":"question mapping","pass":rows.iter().any(|v|v["event"]=="question_mapping_check"&&v["ok"]==true)}));checks.push(json!({"name":"one response under concurrent calls","pass":accepted==1&&!rows.iter().any(|v|v["event"]=="unexpected_or_duplicate_response"),"acceptedCalls":accepted}));
 e.get_rpc().unwrap().shutdown();drop(e);let mut matches=0;for entry in fs::read_dir(&root).unwrap().flatten(){if entry.file_type().unwrap().is_file()&&fs::read(entry.path()).unwrap().windows(secret.len()).any(|w|w==secret.as_bytes()){matches+=1}}
 // Include registered output files, not only SQLite pages.
 for dir in walk(&root.join("workspace")){if fs::read(&dir).unwrap().windows(secret.len()).any(|w|w==secret.as_bytes()){matches+=1}}
 checks.push(json!({"name":"secret echo absent in SQLite, journal and output files","pass":matches==0,"matchingFiles":matches}));
 // A crash fixture loses the volatile mask. Recovery must stop BEFORE fetching
 // unmasked server output; an arbitrary transport error is not the privacy guard.
 let recovered=Engine::open(&root,None).unwrap();{let mut d=recovered.data.lock().unwrap();let mut s=d.snapshot.clone();let j=s.job.as_mut().unwrap();j.status="running".into();j.active_node_id=Some("research".into());j.turn_id=Some("mock-turn-1".into());j.nodes.get_mut("research").unwrap().status="running".into();d.store.save(&s).unwrap();}drop(recovered);
 let recovered=Engine::open(&root,None).unwrap();std::env::set_var("AI_GUILD_QA_DATA_DIR",&root);let(rpc,_)=Rpc::spawn_qa_peer().unwrap();*recovered.rpc.lock().unwrap()=Some(rpc);let err=recovered.control("reconcile".into()).err().unwrap_or_default();checks.push(json!({"name":"restart without volatile secret mask blocks unmasked recovery","pass":err.contains("秘密回答")}));recovered.get_rpc().unwrap().shutdown();
 let(e,root)=setup("file");let a=approval(&e);checks.push(json!({"name":"file approval shows actual proposed path and diff","pass":a.details.contains("MOCK_APPROVED_FILE")&&a.details.contains("file.txt")}));e.answer(a.id,"decline".into(),String::new()).unwrap();finish(&e);checks.push(json!({"name":"file decline","pass":!root.join("file.txt").exists()}));e.get_rpc().unwrap().shutdown();
 let(e,root)=setup("command");let a=approval(&e);e.answer(a.id,"accept".into(),String::new()).unwrap();finish(&e);checks.push(json!({"name":"command accept","pass":root.join("command.txt").exists()}));e.get_rpc().unwrap().shutdown();
 let(e,root)=setup("command");let a=approval(&e);e.answer(a.id,"decline".into(),String::new()).unwrap();finish(&e);checks.push(json!({"name":"command decline","pass":!root.join("command.txt").exists()}));e.get_rpc().unwrap().shutdown();
 let(e,root)=setup("file");let a=approval(&e);e.answer(a.id,"accept".into(),String::new()).unwrap();finish(&e);checks.push(json!({"name":"file accept","pass":root.join("file.txt").exists()}));e.get_rpc().unwrap().shutdown();
 let(e,_)=setup("two-requests");until(||e.snapshot().approvals.len()==2);let a=approval(&e);e.answer(a.id.clone(),"decline".into(),String::new()).unwrap();until(||e.snapshot().approvals.iter().find(|x|x.id==a.id).unwrap().resolved);checks.push(json!({"name":"separate request remains awaiting after first response","pass":e.snapshot().job.unwrap().status=="awaiting_approval"}));let a=approval(&e);e.answer(a.id,"decline".into(),String::new()).unwrap();finish(&e);e.get_rpc().unwrap().shutdown();
 let(e,_)=setup("wait");let a=approval(&e);e.control("stop".into()).unwrap();finish(&e);checks.push(json!({"name":"formal interrupt clears approval and rejects late answer","pass":e.snapshot().job.unwrap().status=="cancelled"&&e.answer(a.id,"accept".into(),String::new()).is_err()}));e.get_rpc().unwrap().shutdown();
 let(e,_)=setup("stale");let a=approval(&e);finish(&e);checks.push(json!({"name":"expired request resolved","pass":e.snapshot().approvals.iter().find(|x|x.id==a.id).unwrap().resolved}));checks.push(json!({"name":"late answer rejected","pass":e.answer(a.id,"accept".into(),String::new()).is_err()}));e.get_rpc().unwrap().shutdown();
 let(e,_)=setup("wrong-turn");finish(&e);checks.push(json!({"name":"wrong turn output excluded","pass":!e.snapshot().job.unwrap().nodes["research"].output.contains("WRONG_TURN_CONTENT")}));e.get_rpc().unwrap().shutdown();
 let base=PathBuf::from(std::env::var_os("AI_GUILD_TEST_ROOT").unwrap());let root=base.join(format!("loaded-two-stages-{}",id()));fs::create_dir_all(&root).unwrap();fs::write(root.join(".ai-guild-qa"),"MOCK two-stage loaded ephemeral thread").unwrap();std::env::set_var("AI_GUILD_QA_DATA_DIR",&root);let e=Engine::open(&root,None).unwrap();let(rpc,_)=Rpc::spawn_qa_peer().unwrap();*e.rpc.lock().unwrap()=Some(rpc);e.update(|s|{s.workflow.nodes.truncate(2);s.workflow.edges.retain(|edge|edge.from_node_id=="research"&&edge.to_node_id=="writing");for n in &mut s.workflow.nodes{n.work_instruction="QA_CASE=loaded-only".into();}Ok(())}).unwrap();e.start("OFFLINE QA_CASE=loaded-only".into()).unwrap();finish(&e);let rows=peer_records(&root);checks.push(json!({"name":"loaded ephemeral thread reused across stages without disk resume","pass":e.snapshot().job.as_ref().unwrap().status=="completed"&&e.snapshot().job.as_ref().unwrap().artifacts.len()==2&&!rows.iter().any(|r|r["event"]=="disk_resume_attempt")}));e.get_rpc().unwrap().shutdown();
 let out=PathBuf::from(std::env::var_os("AI_GUILD_TEST_ROOT").unwrap()).join("mock-regression-result.json");fs::write(out,serde_json::to_vec_pretty(&json!({"classification":"MOCK_ONLY","realInferenceCount":0,"checks":checks})).unwrap()).unwrap();let failures:Vec<_>=checks.iter().filter(|c|c["pass"]!=true).map(|c|c["name"].as_str().unwrap()).collect();assert!(failures.is_empty(),"mock failures: {}",failures.join(", "));
}
fn walk(p:&Path)->Vec<PathBuf>{let mut files=vec![];if let Ok(rows)=fs::read_dir(p){for r in rows.flatten(){if r.path().is_dir(){files.extend(walk(&r.path()))}else{files.push(r.path())}}}files}
